import base from "./clients/southdinkers";

// Single active config with shared helpers
const facilityId =
  process.env.REACT_APP_FACILITY_ID || base.facilityId;

const config = {
  ...base,
  facilityId,
  assetPath(relative) {
    const r = String(relative || "").replace(/^\/+/, "");
    const publicUrl = (process.env.PUBLIC_URL || "").replace(/\/$/, "");
    const rawBase = base.assetsBase || "/assets";
    const basePath = (rawBase.endsWith("/")) ? rawBase.slice(0, -1) : rawBase;
    const normalizedBase = basePath.startsWith("/") ? basePath : `/${basePath}`;
    // When homepage is set to "." (CRA), PUBLIC_URL is "." producing relative paths like "./assets/..."
    return `${publicUrl}${normalizedBase}/${r}`;
  },
  getDefaultCourts() {
    const fromCalendar = Array.isArray(base.calendar?.courts) ? base.calendar.courts : null;
    const fromLegacy = Array.isArray(base.courts?.defaultNames) ? base.courts.defaultNames : null;
    const names = fromCalendar?.length
      ? fromCalendar
      : fromLegacy?.length
        ? fromLegacy
        : ["Court 1", "Court 2", "Court 3"];
    return names.map((name, idx) => ({
      id: idx + 1,
      name: typeof name === "string" ? name : `Court ${idx + 1}`,
      players: [],
    }));
  },
};

export default config;
