import React, { useCallback, useEffect, useMemo, useState } from "react";
import { stringToColor, stringToDarkColor } from "../utils/colorHash";

const MAX_RECENT = 3;
const MAX_WINNERS = 2;

const hasScore = (match) => {
  const g = match?.score?.green;
  const b = match?.score?.blue;
  return g != null && g !== "" && b != null && b !== "";
};

const parseDraftScore = (value) => {
  if (value === "" || value == null) return null;
  const n = Number(value);
  return Number.isNaN(n) ? null : n;
};

const formatTimeAgo = (endTime, now) => {
  if (!endTime) return "";
  const sec = Math.max(0, Math.floor((now - endTime) / 1000));
  if (sec < 60) return `${sec}s ago`;
  const min = Math.floor(sec / 60);
  const rem = sec % 60;
  if (min < 60) return `${min}m ${String(rem).padStart(2, "0")}s ago`;
  const hr = Math.floor(min / 60);
  return `${hr}h ${min % 60}m ago`;
};

const courtLabel = (match) => {
  const raw = String(match?.courtName || match?.courtId || "").trim();
  if (!raw) return "COURT";
  const num = raw.replace(/[^0-9]/g, "");
  return num ? `COURT ${num}` : raw.toUpperCase();
};

const initialLetter = (name = "") => (String(name).trim().charAt(0) || "?").toUpperCase();

function PlayerChip({ player, role, onToggle, disabled }) {
  const isWin = role === "win";
  const isLoss = role === "loss";
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={() => onToggle(player.id)}
      className={`flex items-center gap-1.5 rounded-md border px-1.5 py-1 text-left transition-colors w-full min-w-0 ${
        isWin
          ? "bg-emerald-50 border-emerald-200"
          : isLoss
            ? "bg-slate-50 border-slate-200"
            : "bg-white border-slate-200 hover:border-pt-teal/40"
      } ${disabled ? "opacity-70 cursor-default" : "cursor-pointer"}`}
    >
      <span
        className="h-5 w-5 rounded-full shrink-0 inline-flex items-center justify-center text-white text-[9px] font-black"
        style={{ backgroundColor: stringToColor(player.name || String(player.id)) }}
      >
        {initialLetter(player.name)}
      </span>
      <span className="text-[11px] font-semibold text-slate-800 truncate flex-1">
        {player.name || "—"}
      </span>
      {isWin && (
        <span className="text-[9px] font-bold text-emerald-700 uppercase shrink-0">Win</span>
      )}
      {isLoss && (
        <span className="text-[9px] font-bold text-slate-400 uppercase shrink-0">Loss</span>
      )}
    </button>
  );
}

function RecentMatchCard({
  match,
  now,
  winnerIds,
  onToggleWinner,
  onUpdateMatch,
}) {
  const scored = hasScore(match);
  const lineup = match.lineup || [];
  const winnersSelected = winnerIds.length > 0;

  const [draftBlue, setDraftBlue] = useState(
    match.score?.blue != null ? String(match.score.blue) : ""
  );
  const [draftGreen, setDraftGreen] = useState(
    match.score?.green != null ? String(match.score.green) : ""
  );
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    setDraftBlue(match.score?.blue != null ? String(match.score.blue) : "");
    setDraftGreen(match.score?.green != null ? String(match.score.green) : "");
  }, [match.id, match.score?.blue, match.score?.green]);

  useEffect(() => {
    if (scored) setIsSaving(false);
  }, [scored]);

  const blueNum = parseDraftScore(draftBlue);
  const greenNum = parseDraftScore(draftGreen);
  const scoresReady = blueNum != null && greenNum != null;
  const canSave = winnersSelected && scoresReady && !scored && !isSaving;

  const handleSaveScore = useCallback(() => {
    if (isSaving || scored || !winnersSelected) return;
    const b = parseDraftScore(draftBlue);
    const g = parseDraftScore(draftGreen);
    if (b == null || g == null) return;

    setIsSaving(true);

    const blueSet = new Set(winnerIds.map(String));
    const idMap = new Map(lineup.map((p) => [String(p.id), p.id]));
    const blue = winnerIds.map((x) => idMap.get(String(x)) ?? x);
    const green = lineup.map((p) => p.id).filter((id) => !blueSet.has(String(id)));

    try {
      onUpdateMatch?.(match.id, {
        teams: { blue, green },
        score: { blue: b, green: g },
      });
    } catch (err) {
      setIsSaving(false);
      throw err;
    }
  }, [
    draftBlue,
    draftGreen,
    isSaving,
    lineup,
    match.id,
    onUpdateMatch,
    scored,
    winnerIds,
    winnersSelected,
  ]);

  const courtBadgeColor = stringToDarkColor(courtLabel(match));
  const scoreLabel =
    scored && match.score
      ? `${match.score.blue ?? "—"}-${match.score.green ?? "—"}`
      : null;

  const winPlayers = winnersSelected
    ? lineup.filter((p) => winnerIds.includes(String(p.id)))
    : [];
  const lossOrAll = winnersSelected
    ? lineup.filter((p) => !winnerIds.includes(String(p.id)))
    : lineup;

  return (
    <div className="shrink-0 w-[260px] rounded-xl border border-amber-200/80 bg-white shadow-sm p-2.5 flex flex-col gap-2">
      <div className="flex items-center gap-1.5 min-w-0 flex-wrap">
        <span
          className="h-6 w-6 rounded-full shrink-0 inline-flex items-center justify-center text-white text-[10px] font-black"
          style={{ backgroundColor: courtBadgeColor }}
        >
          {(courtLabel(match).replace(/[^0-9A-Z]/gi, "").charAt(0) || "C").toUpperCase()}
        </span>
        <span className="text-[11px] font-bold text-slate-800 tracking-wide truncate">
          {courtLabel(match)}
        </span>
        {scoreLabel ? (
          <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800">
            {scoreLabel}
          </span>
        ) : (
          <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-amber-50 text-amber-700 border border-amber-100">
            Needs score
          </span>
        )}
        <span className="text-[10px] text-amber-700/80 font-medium whitespace-nowrap ml-auto">
          {formatTimeAgo(match.endTime, now)}
        </span>
      </div>

      <div className="grid grid-cols-2 gap-1.5 flex-1 min-h-0">
        {winnersSelected ? (
          <>
            <div className="space-y-1">
              {winPlayers.map((p) => (
                <PlayerChip
                  key={p.id}
                  player={p}
                  role="win"
                  onToggle={onToggleWinner}
                  disabled={scored}
                />
              ))}
            </div>
            <div className="space-y-1">
              {lossOrAll.map((p) => (
                <PlayerChip
                  key={p.id}
                  player={p}
                  role="loss"
                  onToggle={onToggleWinner}
                  disabled={scored}
                />
              ))}
            </div>
          </>
        ) : (
          <div className="col-span-2 grid grid-cols-2 gap-1.5">
            {lossOrAll.map((p) => (
              <PlayerChip
                key={p.id}
                player={p}
                role="neutral"
                onToggle={onToggleWinner}
                disabled={scored}
              />
            ))}
          </div>
        )}
      </div>

      {!scored && (
        <div className="flex flex-col gap-1.5 pt-0.5 border-t border-slate-100">
          <div className="flex items-center gap-1.5">
            <span className="text-[9px] font-bold text-blue-600 uppercase tracking-wide shrink-0">
              Blue/W
            </span>
            <input
              type="number"
              min={0}
              max={99}
              inputMode="numeric"
              disabled={!winnersSelected || isSaving}
              value={draftBlue}
              onChange={(e) => setDraftBlue(e.target.value)}
              placeholder="11"
              className="w-12 border border-blue-200 rounded-md px-1.5 py-1 text-xs font-bold text-center text-blue-800 disabled:opacity-40 focus:outline-none focus:ring-1 focus:ring-blue-300"
            />
            <span className="text-slate-300 font-bold text-xs">–</span>
            <input
              type="number"
              min={0}
              max={99}
              inputMode="numeric"
              disabled={!winnersSelected || isSaving}
              value={draftGreen}
              onChange={(e) => setDraftGreen(e.target.value)}
              placeholder="5"
              className="w-12 border border-emerald-200 rounded-md px-1.5 py-1 text-xs font-bold text-center text-emerald-800 disabled:opacity-40 focus:outline-none focus:ring-1 focus:ring-emerald-300"
            />
            <span className="text-[9px] font-bold text-emerald-700 uppercase tracking-wide shrink-0">
              Green/L
            </span>
            {!winnersSelected && (
              <span className="text-[9px] text-slate-400 ml-auto">Select winners first</span>
            )}
          </div>
          {winnersSelected && (
            <button
              type="button"
              disabled={!canSave}
              onClick={handleSaveScore}
              className="w-full inline-flex items-center justify-center gap-1.5 rounded-md bg-pt-teal px-2 py-1.5 text-[10px] font-bold text-white hover:bg-pt-teal/90 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {isSaving ? (
                <>
                  <span
                    className="h-2.5 w-2.5 rounded-full border border-white/70 border-t-transparent animate-spin"
                    aria-hidden
                  />
                  Saving…
                </>
              ) : (
                "Save score"
              )}
            </button>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Horizontal strip of the last N completed matches for quick winner + score entry.
 * Rolling window: when a 4th match ends, the oldest drops off (even if scored).
 * Selecting winners tags them as blue team in match history; losers become green.
 */
export default function RecentMatchesStrip({ matches = [], onUpdateMatch }) {
  const [now, setNow] = useState(Date.now());
  // matchId -> winner player id strings (explicit picks; not court auto-teams)
  const [winnerDrafts, setWinnerDrafts] = useState({});

  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);

  const recent = useMemo(() => {
    return [...(matches || [])]
      .filter((m) => m && m.status === "completed" && m.endTime)
      .sort((a, b) => (b.endTime || 0) - (a.endTime || 0))
      .slice(0, MAX_RECENT);
  }, [matches]);

  // Drop drafts for matches that left the strip
  useEffect(() => {
    const keep = new Set(recent.map((m) => String(m.id)));
    setWinnerDrafts((prev) => {
      const next = {};
      let changed = false;
      Object.entries(prev).forEach(([id, ids]) => {
        if (keep.has(String(id))) next[id] = ids;
        else changed = true;
      });
      return changed ? next : prev;
    });
  }, [recent]);

  const getWinnerIds = useCallback(
    (match) => {
      if (hasScore(match)) {
        return (match.teams?.blue || []).map(String);
      }
      return winnerDrafts[match.id] || [];
    },
    [winnerDrafts]
  );

  const toggleWinner = useCallback(
    (match, playerId) => {
      if (hasScore(match)) return;
      const id = String(playerId);
      const lineup = match.lineup || [];

      setWinnerDrafts((prev) => {
        const current = prev[match.id] || [];
        const isWinner = current.includes(id);
        let nextIds;
        if (isWinner) nextIds = current.filter((x) => x !== id);
        else if (current.length >= MAX_WINNERS) return prev;
        else nextIds = [...current, id];

        const blueSet = new Set(nextIds);
        const idMap = new Map(lineup.map((p) => [String(p.id), p.id]));
        const blue = nextIds.map((x) => idMap.get(x) ?? x);
        const green = lineup.map((p) => p.id).filter((pid) => !blueSet.has(String(pid)));

        onUpdateMatch?.(match.id, { teams: { blue, green } });

        return { ...prev, [match.id]: nextIds };
      });
    },
    [onUpdateMatch]
  );

  if (recent.length === 0) return null;

  return (
    <div className="shrink-0 mt-2 pt-2 border-t border-pt-teal/10">
      <div className="flex items-baseline gap-2 mb-1.5 px-0.5">
        <h3 className="text-[10px] font-bold uppercase tracking-wider text-amber-800/80">
          Recently Played
        </h3>
        <span className="text-[10px] text-slate-400">
          Tap winners (blue team) · enter score · Save
        </span>
        <span className="text-[10px] text-slate-300 ml-auto">Last {MAX_RECENT}</span>
      </div>
      <div className="flex gap-2 overflow-x-auto pb-1">
        {recent.map((match) => (
          <RecentMatchCard
            key={match.id}
            match={match}
            now={now}
            winnerIds={getWinnerIds(match)}
            onToggleWinner={(playerId) => toggleWinner(match, playerId)}
            onUpdateMatch={onUpdateMatch}
          />
        ))}
      </div>
    </div>
  );
}
