import React from "react";

const levelEmoji = {
  Newbie: "⚪",
  Beginner: "🟡",
  "L.Inter": "🟢",
  "H.Inter": "🔵",
  Advance: "🟣",
};

const confidenceLabel = (pct, success) => {
  if (!success) return "Conflicted fallback";
  if (pct >= 80) return "Excellent match";
  if (pct >= 50) return "Good match";
  if (pct >= 25) return "Acceptable match";
  return "Poor match";
};

const confidenceColor = (pct) => {
  if (pct >= 75) return "bg-emerald-500";
  if (pct >= 50) return "bg-amber-500";
  if (pct >= 25) return "bg-orange-500";
  return "bg-red-500";
};

const SidePanel = ({ title, letter, color, players = [] }) => (
  <div
    className="flex-1 min-w-[140px] rounded-2xl border-2 p-4 shadow-inner"
    style={{ borderColor: color, background: `${color}12` }}
  >
    <div className="flex items-center gap-2 mb-3">
      <span
        className="inline-flex w-10 h-10 rounded-xl items-center justify-center text-lg font-black text-white shadow-md"
        style={{ backgroundColor: color }}
      >
        {letter || "?"}
      </span>
      <div>
        <div className="text-[10px] uppercase tracking-wider text-slate-500 font-semibold">Team</div>
        <div className="text-lg font-display font-bold text-slate-900 leading-tight">{title}</div>
      </div>
    </div>
    <ul className="space-y-3">
      {players.map((p) => (
        <li key={p.id} className="rounded-xl bg-white/90 border border-white/80 px-3 py-2 shadow-sm">
          <div className="font-semibold text-slate-800">{p.name}</div>
          <div className="text-[11px] text-slate-500">
            {levelEmoji[p.level] || "⚪"} {p.level} · {p.gender}
          </div>
          <div className="text-[10px] text-slate-400 mt-1">
            {p._wait || 0}m wait · {p._matches ?? 0} played
          </div>
        </li>
      ))}
    </ul>
  </div>
);

const CheckRow = ({ check }) => {
  const statusStyle = {
    pass: "text-emerald-700 bg-emerald-50 border-emerald-100",
    warn: "text-amber-700 bg-amber-50 border-amber-100",
    fail: "text-red-700 bg-red-50 border-red-100",
  };
  const statusIcon = { pass: "✓", warn: "⚠", fail: "✕" };
  return (
    <div className={`rounded-lg border px-3 py-2 ${statusStyle[check.status] || statusStyle.pass}`}>
      <div className="text-xs font-semibold uppercase tracking-wide">
        {statusIcon[check.status] || "•"} {check.label}
      </div>
      <div className="text-xs mt-1">{check.reason}</div>
    </div>
  );
};

export default function MatchProposalVersusModal({
  isOpen,
  proposal,
  showDisclaimer = true,
  onConfirm,
  onReGenerate,
  onClose,
  isRegenerating = false,
}) {
  if (!isOpen || !proposal) return null;

  const {
    success,
    usedPlayers = [],
    teamMeta,
    confidencePct = 0,
    checks = [],
    reason,
    diagnostics = {},
    teamsSettingsSnapshot,
  } = proposal;

  const byId = new Map(usedPlayers.map((p) => [String(p.id), p]));
  const sideAPlayers = (teamMeta?.sideA?.players || []).map((id) => byId.get(String(id))).filter(Boolean);
  const sideBPlayers = (teamMeta?.sideB?.players || []).map((id) => byId.get(String(id))).filter(Boolean);

  const ts = teamsSettingsSnapshot || {};

  return (
    <div className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4" onClick={onClose}>
      <div
        className="w-full max-w-4xl max-h-[92vh] overflow-y-auto rounded-2xl border border-slate-200 bg-white shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div
          className={`px-6 py-5 text-white ${success ? "bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900" : "bg-gradient-to-br from-amber-700 to-orange-800"}`}
        >
          <div className="flex items-start justify-between gap-4">
            <div>
              <div className="text-xl font-display font-bold tracking-tight">
                {success ? "Team vs Team" : "No clean team match"}
              </div>
              <div className="text-xs text-white/80 mt-1">Review sides before sending to queue</div>
            </div>
            <button type="button" onClick={onClose} className="text-white/80 hover:text-white text-2xl leading-none">
              ×
            </button>
          </div>
        </div>

        <div className="p-6 space-y-5">
          {showDisclaimer && (
            <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs text-amber-900">
              <span className="font-semibold">Note:</span> Smaller team pools may repeat pairings. Session repeat rules follow Team Settings below.
            </div>
          )}

          <div className="flex flex-col md:flex-row items-stretch md:items-center gap-4 md:gap-2">
            <SidePanel
              title={teamMeta?.sideA?.name || "Side A"}
              letter={teamMeta?.sideA?.letter}
              color={teamMeta?.sideA?.color || "#22C55E"}
              players={sideAPlayers}
            />
            <div className="flex md:flex-col items-center justify-center shrink-0 gap-2 py-2 md:py-0">
              <div className="text-4xl md:text-5xl font-black italic text-slate-200 select-none">VS</div>
            </div>
            <SidePanel
              title={teamMeta?.sideB?.name || "Side B"}
              letter={teamMeta?.sideB?.letter}
              color={teamMeta?.sideB?.color || "#3B82F6"}
              players={sideBPlayers}
            />
          </div>

          <div className="rounded-xl border border-slate-100 bg-slate-50 px-4 py-3 text-[11px] text-slate-600 grid sm:grid-cols-2 gap-x-4 gap-y-1">
            <div>
              <span className="font-semibold text-slate-700">Level mode:</span> {ts.levelMode || "balanced"}
            </div>
            <div>
              <span className="font-semibold text-slate-700">Rotation:</span> {ts.pairRotationStrength || "normal"}
            </div>
            <div>
              <span className="font-semibold text-slate-700">3-player repeat block:</span>{" "}
              {ts.enforceSessionRepeatThreePlayer !== false ? "On" : "Off"}
            </div>
            <div>
              <span className="font-semibold text-slate-700">Exact-4 repeat block:</span>{" "}
              {ts.enforceSessionRepeatFourExact !== false ? "On" : "Off"}
            </div>
          </div>

          {success && (
            <div className="rounded-lg border border-slate-200 p-3">
              <div className="flex items-center justify-between text-xs font-semibold">
                <span>{confidenceLabel(confidencePct, success)}</span>
                <span>{confidencePct}%</span>
              </div>
              <div className="mt-2 h-2 w-full rounded-full bg-slate-100 overflow-hidden">
                <div className={`h-full ${confidenceColor(confidencePct)}`} style={{ width: `${confidencePct}%` }} />
              </div>
            </div>
          )}

          <div className="text-[11px] text-slate-500">
            Checked {diagnostics.totalCombinationsChecked ?? 0} combinations • Valid {diagnostics.validCombinationsFound ?? 0}
          </div>
          {reason && <div className="text-xs text-slate-600">{reason}</div>}

          <div className="space-y-2">
            <div className="text-sm font-semibold text-slate-700">Checks</div>
            {checks.map((check) => (
              <CheckRow key={check.id} check={check} />
            ))}
          </div>
        </div>

        <div className="sticky bottom-0 bg-white border-t border-slate-200 px-6 py-4 flex justify-end gap-2">
          {success ? (
            <>
              <button
                type="button"
                onClick={onReGenerate}
                disabled={isRegenerating}
                className="px-4 py-2 rounded-xl border border-slate-200 text-slate-700 text-xs font-semibold hover:bg-slate-50"
              >
                {isRegenerating ? "Searching…" : "Try Different"}
              </button>
              <button
                type="button"
                onClick={onConfirm}
                className="px-4 py-2 rounded-xl bg-pt-teal text-white text-xs font-semibold shadow-md"
              >
                Queue this match
              </button>
            </>
          ) : (
            <button type="button" onClick={onClose} className="px-4 py-2 rounded-xl bg-amber-600 text-white text-xs font-semibold">
              Close
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
