import React from "react";

export default function SurfaceCard({
  title,
  description,
  actions,
  children,
  className = "",
  bodyClassName = "",
  padded = true,
  accent = false, // adds teal left border
}) {
  const hasHeader = Boolean(title || description || actions);
  const innerSpacing = `${padded ? "px-4 pb-4" : ""} ${bodyClassName || (hasHeader ? "mt-3" : "")
    }`.trim();

  return (
    <section
      className={`admin-card ${accent ? 'accent-left' : ''} ${className}`.trim()}
    >
      {(title || description || actions) && (
        <header className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between px-4 pt-4">
          <div>
            {title && <h2 className="section-label">{title}</h2>}
            {description && (
              <p className="text-xs text-slate-500 mt-1 max-w-prose">{description}</p>
            )}
          </div>
          {actions && <div className="flex items-center gap-2">{actions}</div>}
        </header>
      )}
      <div className={innerSpacing || undefined}>{children}</div>
    </section>
  );
}
