// SideNav.js - Refactored for Mobile Drawer — Dark Navy Professional
import React from "react";
import { NavLink, useNavigate } from "react-router-dom";
import { useAppState } from "../../../app/providers";
import { selectQueueState } from "../../../state/selectors";
import { X, LayoutDashboard, Users, CalendarDays, History, Settings, LogOut, Trophy } from "lucide-react";

const icons = {
  dashboard: <LayoutDashboard className="w-4 h-4" />,
  queue: <Users className="w-4 h-4" />,
  calendar: <CalendarDays className="w-4 h-4" />,
  leaderboards: <Trophy className="w-4 h-4" />,
  reports: <History className="w-4 h-4" />,
  settings: <Settings className="w-4 h-4" />,
  logout: <LogOut className="w-4 h-4" />,
};

export default function SideNav({ collapsed, onToggle, mobileOpen, onMobileClose }) {
  const { userRole, logout } = useAppState(selectQueueState);
  const navigate = useNavigate();

  const base =
    "flex items-center gap-3 w-full px-3 py-2.5 rounded-lg text-sm font-condensed font-semibold tracking-wide transition-all duration-150 relative";

  // Active: teal left-border + subtle background
  const active =
    "bg-white/10 text-white before:absolute before:left-0 before:top-1/2 before:-translate-y-1/2 before:h-5 before:w-0.5 before:bg-pt-orange before:rounded-full";
  const idle = "text-white/55 hover:text-white hover:bg-white/5";

  const widthClass = collapsed ? "w-14" : "w-56";

  const handleLogout = () => {
    logout();
    navigate("/");
  };

  const Content = (
    <div className="flex flex-col h-full bg-display">

      {/* Brand + toggle */}
      <div className="flex items-center justify-between px-4 py-3.5 shrink-0">

        {/* Mobile: Close Button */}
        <div className="md:hidden flex items-center justify-between w-full">
          <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-white/50">Menu</span>
          <button onClick={onMobileClose} className="p-1.5 rounded-lg hover:bg-white/10 text-white/70 hover:text-white transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Desktop: Toggle Button */}
        <div className="hidden md:flex items-center justify-between w-full">
          <button
            type="button"
            onClick={onToggle}
            className="flex items-center justify-center w-7 h-7 rounded-lg bg-white/10 text-white/70 hover:bg-white/20 hover:text-white transition-colors text-sm"
            aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            <span aria-hidden="true" className="text-base leading-none">☰</span>
          </button>

          {!collapsed && (
            <div className="ml-2 text-[10px] font-condensed font-black uppercase tracking-[0.25em] text-white/35">
              Menu
            </div>
          )}
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-2.5 py-3 space-y-1 overflow-y-auto custom-scrollbar">

        {/* Admin Only: Dashboard */}
        {userRole === "admin" && (
          <NavLink
            to="/dashboard"
            onClick={onMobileClose}
            className={({ isActive }) => `${base} ${isActive ? active : idle}`}
            title="Dashboard"
          >
            {icons.dashboard}
            <span className={collapsed ? "md:hidden" : ""}>Dashboard</span>
          </NavLink>
        )}

        {/* Everyone: Queue */}
        <NavLink
          to="/queue"
          end
          onClick={onMobileClose}
          className={({ isActive }) => `${base} ${isActive ? active : idle}`}
          title="Queue (OP)"
        >
          {icons.queue}
          <span className={collapsed ? "md:hidden" : ""}>Queue (OP)</span>
        </NavLink>

        {/* Everyone: Calendar V2 */}
        <NavLink
          to="/calendar-v2"
          onClick={onMobileClose}
          className={({ isActive }) => `${base} ${isActive ? active : idle}`}
          title="Calendar V2"
        >
          {icons.calendar}
          <span className={collapsed ? "md:hidden" : ""}>Calendar V2</span>
        </NavLink>

        <NavLink
          to="/leaderboards"
          onClick={onMobileClose}
          className={({ isActive }) => `${base} ${isActive ? active : idle}`}
          title="Leaderboards"
        >
          {icons.leaderboards}
          <span className={collapsed ? "md:hidden" : ""}>Leaderboards</span>
        </NavLink>

        {/* Admin Only: History & Settings */}
        {userRole === "admin" && (
          <>
            <NavLink
              to="/history"
              onClick={onMobileClose}
              className={({ isActive }) => `${base} ${isActive ? active : idle}`}
              title="History"
            >
              {icons.reports}
              <span className={collapsed ? "md:hidden" : ""}>History</span>
            </NavLink>

            <NavLink
              to="/settings"
              onClick={onMobileClose}
              className={({ isActive }) => `${base} ${isActive ? active : idle}`}
              title="Settings"
            >
              {icons.settings}
              <span className={collapsed ? "md:hidden" : ""}>Settings</span>
            </NavLink>
          </>
        )}
      </nav>

      {/* Bottom: Logout */}
      <div className="p-2.5 shrink-0 mb-safe">
        <button
          onClick={handleLogout}
          className={`${base} text-red-400/70 hover:text-red-400 hover:bg-red-500/10`}
          title="Switch Role"
        >
          {icons.logout}
          <span className={collapsed ? "md:hidden" : ""}>Switch Role</span>
        </button>
      </div>
    </div>
  );

  return (
    <>
      {/* Mobile Drawer Overlay */}
      {mobileOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 md:hidden transition-opacity"
          onClick={onMobileClose}
          aria-hidden="true"
        />
      )}

      {/* Mobile Sidebar (Fixed Drawer) */}
      <aside         className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-display shadow-xl transform transition-transform duration-300 md:hidden
        ${mobileOpen ? "translate-x-0" : "-translate-x-full"}
      `}>
        {Content}
      </aside>

      {/* Desktop Sidebar (Static) */}
      <aside
        className={`hidden md:flex flex-col flex-shrink-0 bg-display text-white transition-all duration-300 relative ${widthClass}`}
      >
        {Content}
      </aside>
    </>
  );
}
