import React, { useMemo } from "react";

const sanitize = (n) => {
  const v = Number(n);
  return Number.isFinite(v) && v > 0 ? v : 0;
};

export default function IncomeChart({
  data = [],
  height = 180,
  color = "#0d9488",
}) {
  const points = useMemo(() => {
    if (!Array.isArray(data)) return [];
    return data.map((d) => ({
      label: d?.label || "",
      value: sanitize(d?.value),
    }));
  }, [data]);

  if (points.length < 2) {
    return (
      <div
        className="flex items-center justify-center text-xs text-slate-400"
        style={{ height }}
      >
        Not enough data for trend
      </div>
    );
  }

  const values = points.map((d) => d.value);
  const rawMax = Math.max(...values, 0);
  // Pad headroom so the stroke never sits on the top edge; keep a readable floor.
  const max = Math.max(rawMax * 1.1, rawMax > 0 ? rawMax : 1, 1);

  const padX = 2;
  const padY = 8;
  const plotW = 100 - padX * 2;
  const plotH = 100 - padY * 2;

  const getX = (i) => padX + (i / (points.length - 1)) * plotW;
  const getY = (v) => padY + plotH - (v / max) * plotH;

  let lineD = "";
  let areaD = "";
  points.forEach((d, i) => {
    const x = getX(i);
    const y = getY(d.value);
    const cmd = i === 0 ? "M" : "L";
    lineD += `${cmd} ${x},${y} `;
    if (i === 0) areaD = `M ${x},${padY + plotH} L ${x},${y} `;
    else areaD += `L ${x},${y} `;
  });
  areaD += `L ${getX(points.length - 1)},${padY + plotH} Z`;

  const formatAxis = (n) => {
    if (n >= 1000) return `${Math.round(n / 100) / 10}k`;
    return Math.round(n).toLocaleString();
  };

  return (
    <div className="w-full flex flex-col overflow-hidden" style={{ height }}>
      <div className="relative flex-1 min-h-0 overflow-hidden">
        <svg
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          className="absolute inset-0 w-full h-full overflow-hidden"
          aria-hidden
        >
          <line
            x1={padX}
            y1={padY}
            x2={100 - padX}
            y2={padY}
            stroke="#f1f5f9"
            strokeWidth="1"
            vectorEffect="non-scaling-stroke"
          />
          <line
            x1={padX}
            y1={50}
            x2={100 - padX}
            y2={50}
            stroke="#f1f5f9"
            strokeWidth="1"
            vectorEffect="non-scaling-stroke"
          />
          <line
            x1={padX}
            y1={padY + plotH}
            x2={100 - padX}
            y2={padY + plotH}
            stroke="#e2e8f0"
            strokeWidth="1"
            vectorEffect="non-scaling-stroke"
          />
          <path d={areaD} fill={color} fillOpacity="0.12" />
          <path
            d={lineD}
            fill="none"
            stroke={color}
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            vectorEffect="non-scaling-stroke"
          />
        </svg>

        <div className="pointer-events-none absolute top-0 left-0 z-10 text-[10px] text-slate-400 bg-white/80 px-1 rounded">
          {formatAxis(rawMax || max)}
        </div>
        <div className="pointer-events-none absolute top-1/2 -translate-y-1/2 left-0 z-10 text-[10px] text-slate-400 bg-white/80 px-1 rounded">
          {formatAxis((rawMax || max) / 2)}
        </div>
      </div>

      <div className="h-6 flex-shrink-0 flex justify-between items-center text-[10px] text-slate-400 px-1 mt-1 border-t border-slate-50 pt-1">
        <span>{points[0]?.label}</span>
        <span>{points[Math.floor(points.length / 2)]?.label}</span>
        <span>{points[points.length - 1]?.label}</span>
      </div>
    </div>
  );
}
