import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { resolveMatchSidesForDisplay } from "../../../state/matchSides";

const formatDateTime = (value) => {
  if (!value) return "--\n--";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "--\n--";
  const day = date.toLocaleDateString([], { month: "short", day: "2-digit" });
  const time = date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  return `${day}\n${time}`;
};

const formatDuration = (ms) => {
  if (!ms || ms <= 0) return "00:00";
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60)
    .toString()
    .padStart(2, "0");
  const seconds = (totalSeconds % 60).toString().padStart(2, "0");
  return `${minutes}:${seconds}`;
};

const PlayerTeamCard = ({
  player,
  currentTeam,
  onSelectTeam,
  greenDisabled,
  blueDisabled,
  sideBadge,
  showPairingButtons = true,
}) => {
  const base =
    "flex w-full flex-wrap items-center gap-x-2 gap-y-1 rounded-xl border px-2 py-1.5 shadow-sm transition-all min-h-[34px] bg-white border-gray-200";

  const name = player.name ? player.name.toUpperCase() : "UNKNOWN";

  const buttonBase =
    "px-1.5 py-0.5 rounded-md border text-[10px] font-semibold uppercase transition-colors leading-tight";

  const greenSelected = currentTeam === "green";
  const blueSelected = currentTeam === "blue";

  return (
    <div className={base}>
      <div className="flex min-w-0 flex-1 items-center gap-1.5">
        {sideBadge ? (
          <span
            className="h-5 min-w-[1.25rem] px-1 shrink-0 rounded inline-flex items-center justify-center text-[10px] font-bold text-white shadow-sm"
            style={{ backgroundColor: sideBadge.color }}
            title={sideBadge.name}
          >
            {(sideBadge.letter || "?").toUpperCase()}
          </span>
        ) : (
          <span className="h-2.5 w-2.5 shrink-0 rounded-full bg-gradient-to-br from-blue-400 to-blue-600 shadow-inner" />
        )}
        <span className="truncate text-[11px] font-semibold tracking-wide text-gray-700">{name}</span>
      </div>
      {showPairingButtons && (
        <div className="flex shrink-0 items-center gap-1 ml-auto">
          <button
            type="button"
            onClick={() => onSelectTeam("green")}
            className={`${buttonBase} ${greenSelected
                ? "bg-green-600 text-white border-green-600 shadow"
                : greenDisabled
                  ? "bg-white text-green-400 border-green-200 cursor-not-allowed opacity-60"
                  : "bg-white text-green-600 border-green-400 hover:bg-green-50"
              }`}
            disabled={greenDisabled && !greenSelected}
          >
            G
          </button>
          <button
            type="button"
            onClick={() => onSelectTeam("blue")}
            className={`${buttonBase} ${blueSelected
                ? "bg-blue-600 text-white border-blue-600 shadow"
                : blueDisabled
                  ? "bg-white text-blue-400 border-blue-200 cursor-not-allowed opacity-60"
                  : "bg-white text-blue-600 border-blue-400 hover:bg-blue-50"
              }`}
            disabled={blueDisabled && !blueSelected}
          >
            B
          </button>
        </div>
      )}
    </div>
  );
};

const ScoreSummaryCard = ({
  score,
  onChange,
  winner,
  onQuickWin,
  labelGreen = "Green",
  labelBlue = "Blue",
  colorGreen = "#15803D",
  colorBlue = "#1D4ED8",
  useTeamColors = false,
}) => {
  const handleLabelActivate = (team) => {
    if (typeof onQuickWin === "function") onQuickWin(team);
  };

  return (
    <div className="w-full rounded-2xl border border-slate-200 bg-slate-50 px-2.5 py-2 shadow-sm min-h-[40px] flex flex-col justify-center">
      <div className="flex items-center justify-around gap-4">
        {[
          {
            label: labelGreen,
            key: "green",
            labelClass: "text-green-700",
            inputClass: "border-green-200 focus:ring-green-200",
            color: colorGreen,
          },
          {
            label: labelBlue,
            key: "blue",
            labelClass: "text-blue-700",
            inputClass: "border-blue-200 focus:ring-blue-200",
            color: colorBlue,
          },
        ].map(({ label, key, labelClass, inputClass, color }) => (
          <label key={key} className="flex flex-col items-center gap-1">
            <span
              role="button"
              tabIndex={0}
              className={`text-xs font-semibold uppercase tracking-wide ${labelClass} cursor-pointer select-none`}
              style={useTeamColors ? { color } : undefined}
              onClick={() => handleLabelActivate(key)}
              onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                  event.preventDefault();
                  handleLabelActivate(key);
                }
              }}
            >
              {label}
            </span>
            <input
              type="number"
              min="0"
              value={score[key] ?? ""}
              onChange={(e) => onChange(key, e.target.value)}
              className={`h-10 w-14 rounded-xl border bg-white text-center text-[12px] font-semibold text-slate-700 outline-none transition focus:ring-2 ${inputClass}`}
              placeholder="0"
              inputMode="numeric"
            />
          </label>
        ))}
      </div>
      {winner && (
        <div className="mt-1 flex justify-center">
          <span
            className={`text-[10px] font-semibold px-2 py-0.5 rounded ${winner === "green"
                ? "bg-green-100 text-green-700"
                : winner === "blue"
                  ? "bg-blue-100 text-blue-700"
                  : "bg-gray-100 text-gray-600"
              }`}
            style={
              useTeamColors && (winner === "green" || winner === "blue")
                ? {
                    backgroundColor: winner === "green" ? colorGreen : colorBlue,
                    color: "#FFFFFF",
                  }
                : undefined
            }
          >
            {winner === "green" ? `${labelGreen} Win` : winner === "blue" ? `${labelBlue} Win` : "Tie"}
          </span>
        </div>
      )}
    </div>
  );
};

const MAX_TEAM_SIZE = 2;
const EMPTY_TEAM = Object.freeze([]);

function MatchHistoryRow({ match, onUpdate }) {
  const matchSides = useMemo(() => resolveMatchSidesForDisplay(match), [match]);
  const useTeamColors = !!match?.teamMeta?.sideA?.name || !!match?.teamMeta?.sideB?.name;
  const players = useMemo(() => match.lineup || [], [match.lineup]);
  const teamsGreen = match.teams?.green || EMPTY_TEAM;
  const teamsBlue = match.teams?.blue || EMPTY_TEAM;
  const scoreGreen = match.score?.green ?? "";
  const scoreBlue = match.score?.blue ?? "";
  const [draftTeams, setDraftTeams] = useState(() => ({
    green: [...teamsGreen],
    blue: [...teamsBlue],
  }));
  const [draftScore, setDraftScore] = useState(() => ({
    green: scoreGreen,
    blue: scoreBlue,
  }));
  const draftTeamsRef = useRef(draftTeams);
  const draftScoreRef = useRef(draftScore);

  const persistMatch = useCallback(
    (teams, score) => {
      onUpdate(match.id, {
        teams,
        score: {
          green: score.green,
          blue: score.blue,
        },
      });
    },
    [match.id, onUpdate]
  );

  useEffect(() => {
    setDraftTeams({
      green: [...teamsGreen],
      blue: [...teamsBlue],
    });
  }, [match.id, teamsGreen, teamsBlue]);

  useEffect(() => {
    setDraftScore({
      green: scoreGreen,
      blue: scoreBlue,
    });
  }, [match.id, scoreGreen, scoreBlue]);

  useEffect(() => {
    draftTeamsRef.current = draftTeams;
  }, [draftTeams]);

  useEffect(() => {
    draftScoreRef.current = draftScore;
  }, [draftScore]);

  const updateTeams = useCallback(
    (updater) => {
      setDraftTeams((prev) => {
        const next = typeof updater === "function" ? updater(prev) : updater;
        persistMatch(next, draftScoreRef.current);
        return next;
      });
    },
    [persistMatch]
  );

  const updateScore = useCallback(
    (updater) => {
      setDraftScore((prev) => {
        const next = typeof updater === "function" ? updater(prev) : updater;
        persistMatch(draftTeamsRef.current, next);
        return next;
      });
    },
    [persistMatch]
  );

  const applyTeam = (playerId, team) => {
    updateTeams((prev) => {
      const wasGreen = prev.green.includes(playerId);
      const wasBlue = prev.blue.includes(playerId);

      let green = prev.green.filter((id) => id !== playerId);
      let blue = prev.blue.filter((id) => id !== playerId);

      if (team === "green") {
        if (wasGreen) return { green, blue };
        if (green.length >= MAX_TEAM_SIZE) return prev;
        green = [...green, playerId];
      } else if (team === "blue") {
        if (wasBlue) return { green, blue };
        if (blue.length >= MAX_TEAM_SIZE) return prev;
        blue = [...blue, playerId];
      }

      return { green, blue };
    });
  };

  const handleScoreChange = (team, value) => {
    if (team !== "green" && team !== "blue") return;
    updateScore((prev) => ({ ...prev, [team]: value }));
  };

  const winner = match.winner;

  const handleQuickWin = useCallback(
    (team) => {
      if (team !== "green" && team !== "blue") return;
      const quickScore =
        team === "green"
          ? { green: 11, blue: 0 }
          : { green: 0, blue: 11 };
      updateScore(() => quickScore);
    },
    [updateScore]
  );

  return (
    <tr className="border-b align-middle">
      <td className="w-24 p-2 pr-1 text-[11px] text-gray-600 align-middle whitespace-pre-line">
        {formatDateTime(match.startTime)}
      </td>
      <td className="w-8 p-2 pl-0 text-sm font-semibold text-gray-700 text-center align-middle">
        {match.courtId ?? match.courtName ?? "--"}
      </td>
      <td className="w-12 p-2 text-[11px] text-gray-500 text-center align-middle">{formatDuration(match.durationMs)}</td>
      <td className="p-2">
        <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
          {/* Dynamic Display: If teams are empty/unassigned, show simple list, else show Team alignment */}
          {(teamsGreen.length === 0 && teamsBlue.length === 0) ? (
            <div className="col-span-1 sm:col-span-2 flex flex-wrap gap-2">
              {players.map(p => (
                <div key={p.id} className="bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 flex items-center gap-1.5">
                  <span className="h-2 w-2 rounded-full bg-slate-400"></span>
                  <span className="text-xs font-medium text-slate-700">{p.name}</span>
                  {/* Allow editing teams by treating this as Unassigned */}
                  <div className="flex ml-2 scale-75 origin-left opacity-30 hover:opacity-100 transition-opacity">
                    <button onClick={() => applyTeam(p.id, 'green')} className="px-1 border border-green-400 text-green-600 text-[9px] rounded-l hover:bg-green-50">G</button>
                    <button onClick={() => applyTeam(p.id, 'blue')} className="px-1 border border-blue-400 text-blue-600 text-[9px] rounded-r hover:bg-blue-50">B</button>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            players.map((player) => {
              const current = draftTeams.green.includes(player.id)
                ? "green"
                : draftTeams.blue.includes(player.id)
                  ? "blue"
                  : "";
              const sideBadge =
                current === "green"
                  ? {
                      letter: matchSides.green.letter,
                      color: matchSides.green.color,
                      name: matchSides.green.name,
                    }
                  : current === "blue"
                    ? {
                        letter: matchSides.blue.letter,
                        color: matchSides.blue.color,
                        name: matchSides.blue.name,
                      }
                    : null;
              return (
                <PlayerTeamCard
                  key={player.id}
                  player={player}
                  currentTeam={current}
                  onSelectTeam={(team) => applyTeam(player.id, team)}
                  greenDisabled={draftTeams.green.length >= MAX_TEAM_SIZE && current !== "green"}
                  blueDisabled={draftTeams.blue.length >= MAX_TEAM_SIZE && current !== "blue"}
                  sideBadge={sideBadge}
                  showPairingButtons={!useTeamColors}
                />
              );
            })
          )}
        </div>
      </td>
      <td className="w-32 p-2">
        <ScoreSummaryCard
          score={draftScore}
          winner={winner}
          onChange={handleScoreChange}
          onQuickWin={handleQuickWin}
          labelGreen={matchSides.green.name}
          labelBlue={matchSides.blue.name}
          colorGreen={matchSides.green.color}
          colorBlue={matchSides.blue.color}
          useTeamColors={useTeamColors}
        />
      </td>
    </tr>
  );
}

export default function MatchHistoryTable({ matches, onUpdateMatch }) {
  if (!matches || matches.length === 0) {
    return <div className="p-4 text-sm text-gray-500">No matches recorded yet.</div>;
  }

  return (
    <table className="w-full text-xs md:text-[13px]">
      <thead className="bg-gray-100 sticky top-0 z-10">
        <tr>
          <th className="p-2 text-left text-xs uppercase tracking-wide text-gray-500">Date</th>
          <th className="p-2 text-left text-xs uppercase tracking-wide text-gray-500">Court</th>
          <th className="p-2 text-left text-xs uppercase tracking-wide text-gray-500">Duration</th>
          <th className="p-2 text-left text-xs uppercase tracking-wide text-gray-500">Players</th>
          <th className="p-2 text-left text-xs uppercase tracking-wide text-gray-500">Score</th>
        </tr>
      </thead>
      <tbody>
        {matches.map((match) => (
          <MatchHistoryRow key={match.id} match={match} onUpdate={onUpdateMatch} />
        ))}
      </tbody>
    </table>
  );
}
