const SlotsTab = ({ slots, onRemove, onAdd, onUpdateSlotPrice, booking, onToggleSlotPayment, onMarkFree, readOnly, allSlots = [], courts = [], bookingDate, settings = {} }) => {
    // Basic Add Slot Form State
    const [addMode, setAddMode] = useState(false);
    const [courtId, setCourtId] = useState("1"); // Default
    const [startHour, setStartHour] = useState("10"); // Default 10 AM
    const [endHour, setEndHour] = useState("11"); // Default 11 AM

    // Generate operating hours (08:00 starts through 24:00 close)
    const startHours = Array.from({ length: 16 }, (_, i) => i + 8);
    const possibleEndHours = Array.from({ length: 16 }, (_, i) => i + 9);

    // Filter end hours based on start hour (must be > start hour)
    const endHours = possibleEndHours.filter(h => h > parseInt(startHour));

    // Update end hour if it becomes invalid
    React.useEffect(() => {
        if (parseInt(endHour) <= parseInt(startHour)) {
            setEndHour((parseInt(startHour) + 1).toString());
        }
    }, [startHour, endHour]);

    const targetDate = bookingDate || new Date().toLocaleDateString('en-CA');
    const previewRows = React.useMemo(() => {
        const sH = parseInt(startHour, 10);
        const eH = parseInt(endHour, 10);
        if (booking?.type === "OPEN_PLAY_BLOCK") return [];
        return buildHourlySlotPreview(settings, { date: targetDate, startHour: sH, endHour: eH });
    }, [startHour, endHour, targetDate, settings, booking?.type]);

    const handleAdd = () => {
        const sH = parseInt(startHour);
        const eH = parseInt(endHour);
        let cId = parseInt(courtId);

        // Defensive Check: Prevent timestamp usage as Court ID (User Reported Bug)
        if (isNaN(cId) || cId > 10000) {
            console.error("Invalid Court ID detected:", courtId, "-> parsed:", cId);
            alert("There was a problem with the slot you have booked. Please try again or add a slot in the Slots Tab of your Booking.");
            return;
        }

        // Loop from start to end hour
        let addedCount = 0;
        let skippedCount = 0;

        for (let h = sH; h < eH; h++) {
            // Construct Date object from Global Booking Date + Hour
            const targetDate = bookingDate || new Date().toLocaleDateString('en-CA');
            const sTime = new Date(targetDate);
            sTime.setHours(h, 0, 0, 0);

            // Check if invalid date (e.g. if string parsing failed)
            if (isNaN(sTime.getTime())) {
                console.error("Invalid Date Selection");
                return;
            }

            const eTime = new Date(sTime);
            eTime.setHours(h + 1, 0, 0, 0);

            // Check Conflict
            const conflict = allSlots.some(existing => {
                if (existing.status === "CANCELLED") return false;
                if (existing.courtId !== cId) return false;

                // Compare Dates First (optimization)
                if (existing.date !== targetDate) return false;

                const exStart = existing.startTime;
                const exEnd = existing.endTime;
                // Check overlap using minutes
                const targetStart = h * 60;
                const targetEnd = (h + 1) * 60;

                return targetStart < exEnd && targetEnd > exStart;
            });

            if (conflict) {
                skippedCount++;
                continue;
            }

            // Defensive Check: Prevent timestamp usage as Court ID (User Reported Bug)
            if (isNaN(cId) || cId > 1000) {
                console.error("Invalid Court ID detected:", courtId, "-> parsed:", cId);
                toast.error("There is an issue with the selected court. Please refresh the page.");
                return;
            }

            onAdd(booking.id, {
                courtId: cId,
                date: targetDate, // Use Global Date
                startTime: h * 60,
                endTime: (h + 1) * 60,
                price: booking.type === "OPEN_PLAY_BLOCK" ? 0 : getRentalSlotPrice(settings, { date: targetDate, startTime: h * 60 })
            });
            addedCount++;
        }

        if (skippedCount > 0 && addedCount > 0) {
            console.log(`Added ${addedCount} slots, skipped ${skippedCount} conflicts.`);
        }
    };



    // Group slots by Court
    const slotsByCourt = React.useMemo(() => {
        const groups = {};
        slots.forEach(slot => {
            if (!groups[slot.courtId]) groups[slot.courtId] = [];
            groups[slot.courtId].push(slot);
        });
        return groups;
    }, [slots]);

    const courtIds = Object.keys(slotsByCourt).sort((a, b) => Number(a) - Number(b));

    // Collapse logic
    const [expandedCourts, setExpandedCourts] = useState({});

    const toggleCourt = (cId) => {
        setExpandedCourts(prev => ({
            ...prev,
            [cId]: !prev[cId]
        }));
    };

    return (
        <div className="space-y-4">
            <div className="flex justify-between items-center">
                <h3 className="text-sm font-semibold text-slate-900">Active Slots ({slots.length})</h3>
                {!readOnly && (
                    <button
                        onClick={() => setAddMode(!addMode)}
                        className="flex items-center gap-1 text-xs font-medium text-slate-600 hover:text-slate-900 bg-slate-100 px-3 py-1.5 rounded-md hover:bg-slate-200"
                    >
                        <Plus className="h-3 w-3" />
                        Add Slot
                    </button>
                )}
            </div>

            {/* Payment Method Only - Bulk Removed (Moved to Modal) */}
            {/* <div className="bg-slate-50 p-3 rounded-lg border border-slate-200"> ... </div> */}

            {addMode && !readOnly && (
                <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 animate-in fade-in slide-in-from-top-2">
                    <div className="flex gap-2 items-end flex-wrap">
                        <div className="w-[100px]">
                            <label className="text-[10px] font-bold text-slate-400 uppercase">Court</label>
                            <select
                                value={courtId}
                                onChange={e => setCourtId(e.target.value)}
                                className="w-full text-sm border-slate-300 rounded focus:border-slate-900 focus:ring-0 px-2 py-1.5"
                            >
                                {courts.length > 0 ? (
                                    courts.map(c => <option key={c.id} value={c.id}>{c.name}</option>)
                                ) : (
                                    <option disabled>No Courts</option>
                                )}
                            </select>
                        </div>

                        <div className="flex items-center gap-2 flex-1 min-w-[160px]">
                            <div className="flex-1">
                                <label className="text-[10px] font-bold text-slate-400 uppercase">Start</label>
                                <select
                                    value={startHour}
                                    onChange={e => setStartHour(e.target.value)}
                                    className="w-full text-sm border-slate-300 rounded focus:border-slate-900 focus:ring-0 px-2 py-1.5"
                                >
                                    {startHours.map(h => (
                                        <option key={h} value={h}>{formatMinutesAmpm(h * 60)}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="text-slate-400 mt-4">→</div>
                            <div className="flex-1">
                                <label className="text-[10px] font-bold text-slate-400 uppercase">End</label>
                                <select
                                    value={endHour}
                                    onChange={e => setEndHour(e.target.value)}
                                    className="w-full text-sm border-slate-300 rounded focus:border-slate-900 focus:ring-0 px-2 py-1.5"
                                >
                                    {endHours.map(h => (
                                        <option key={h} value={h}>{formatMinutesAmpm(h * 60)}</option>
                                    ))}
                                </select>
                            </div>
                        </div>
                        <button
                            onClick={handleAdd}
                            className="px-4 py-2 bg-slate-900 text-white text-sm font-medium rounded shadow-sm hover:bg-slate-800 h-[36px] mt-auto"
                        >
                            Add
                        </button>
                    </div>

                    {previewRows.length > 0 && (
                        <div className="mt-3 pt-3 border-t border-slate-200 space-y-1">
                            <p className="text-[10px] font-bold text-slate-400 uppercase">Normal hourly rates</p>
                            <p className="text-xs text-slate-500">Add the hours to see the full booking total and any eligible promo packages.</p>
                            {previewRows.map((row) => (
                                <div key={row.startTime} className="flex justify-between text-xs text-slate-600">
                                    <span>{formatSlotTimeRange(row.startTime, row.endTime)}</span>
                                    <span className="font-semibold text-slate-800">₱{row.price.toLocaleString()}</span>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}

            <div className="space-y-3">
                {courtIds.map(cId => {
                    const isExpanded = expandedCourts[cId];
                    const courtSlots = slotsByCourt[cId];

                    // Sort slots by time
                    courtSlots.sort((a, b) => new Date(a.startTime) - new Date(b.startTime));

                    return (
                        <div key={cId} className="border border-slate-200 rounded-lg overflow-hidden">
                            {/* Header */}
                            <button
                                onClick={() => toggleCourt(cId)}
                                className="w-full flex items-center justify-between px-4 py-2.5 bg-slate-50 hover:bg-slate-100 transition-colors"
                            >
                                <div className="flex items-center gap-2">
                                    <span className="font-semibold text-sm text-slate-700">Court {cId}</span>
                                    <span className="px-2 py-0.5 rounded-full bg-slate-200 text-slate-600 text-[10px] font-bold">
                                        {courtSlots.length} Slots
                                    </span>
                                </div>
                                {isExpanded ? <ChevronUp className="h-4 w-4 text-slate-400" /> : <ChevronDown className="h-4 w-4 text-slate-400" />}
                            </button>

                            {/* Body */}
                            {isExpanded && (
                                <table className="min-w-full divide-y divide-slate-200">
                                    <thead className="bg-slate-50">
                                        <tr>
                                            <th className="px-4 py-2 text-left text-[10px] font-bold text-slate-400 uppercase">Time</th>
                                            <th className="px-4 py-2 text-left text-[10px] font-bold text-slate-400 uppercase">Rate (₱)</th>
                                            <th className="px-4 py-2" />
                                        </tr>
                                    </thead>
                                    <tbody className="bg-white divide-y divide-slate-200">
                                        {courtSlots.map((slot, idx) => {
                                            const timeStr = formatSlotTimeRange(slot.startTime, slot.endTime);

                                            return (
                                                <tr key={slot.slotId || idx}>
                                                    <td className="px-4 py-3 text-sm text-slate-500 whitespace-nowrap w-1/3">
                                                        {timeStr}
                                                    </td>
                                                    <td className="px-4 py-3 text-sm text-slate-500 w-1/3">
                                                        {booking?.type !== "OPEN_PLAY_BLOCK" && (
                                                            !readOnly && onUpdateSlotPrice ? (
                                                                <input
                                                                    type="number"
                                                                    min="0"
                                                                    step="50"
                                                                    value={slot.price ?? 0}
                                                                    onChange={(e) => onUpdateSlotPrice(slot.slotId, e.target.value)}
                                                                    className="w-20 text-sm border border-slate-200 rounded px-2 py-1 focus:ring-slate-900 focus:border-slate-900"
                                                                />
                                                            ) : (
                                                                slot.price > 0 ? `₱${Number(slot.price).toLocaleString()}` : ""
                                                            )
                                                        )}
                                                    </td>
                                                    {/* Payment Toggle Removed - Balance Based Logic now */}
                                                    {/* <td className="px-4 py-3 text-sm">
                                                        <button ... />
                                                    </td> */}
                                                    <td className="px-4 py-3 text-right text-sm font-medium">
                                                        {!readOnly && (
                                                            <button
                                                                onClick={() => onRemove(slot)}
                                                                className="text-slate-400 hover:text-rose-600 transition-colors"
                                                            >
                                                                <Trash2 className="h-4 w-4" />
                                                            </button>
                                                        )}
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            )}
                        </div>
                    );
                })}
            </div>
        </div >
    );
};

const HistoryTab = ({ logs }) => {
    const formatLogTime = (log) => {
        const raw = log.timestamp || log.at;
        if (!raw) return "—";
        const d = new Date(raw);
        if (Number.isNaN(d.getTime())) return "—";
        return d.toLocaleString();
    };

    return (
        <div className="space-y-4">
            <div className="relative border-l-2 border-slate-200 ml-3 space-y-6 py-2">
                {logs.slice().reverse().map((log, idx) => { // Show newest first
                    const actor = log.adminId || log.reviewedBy;
                    const notes = log.details || log.notes;
                    return (
                        <div key={idx} className="relative pl-6">
                            <div className="absolute -left-[9px] top-0 bg-white border-2 border-slate-300 rounded-full h-4 w-4 flex items-center justify-center">
                                <div className="h-1.5 w-1.5 rounded-full bg-slate-400" />
                            </div>
                            <div>
                                <p className="text-xs font-semibold text-slate-700 uppercase tracking-wide">
                                    {log.action.replace(/_/g, " ")}
                                </p>
                                {notes && (
                                    <p className="text-sm text-slate-600 mt-1">{notes}</p>
                                )}
                                {actor && (
                                    <p className="text-xs text-slate-500 mt-1">By: {actor}</p>
                                )}
                                <p className="text-xs text-slate-400 mt-1">
                                    {formatLogTime(log)}
                                </p>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// --- Payment Modal ---
const PaymentModal = ({ onClose, onConfirm, balance, total, currentPaid, paymentMethod, onUpdatePaymentMethod }) => {
    const [amount, setAmount] = useState("");
    const [mode, setMode] = useState(balance < 0 ? "REFUND" : "PAY"); // PAY | REFUND
    const [note, setNote] = useState("");
    const overpaidAmount = balance < 0 ? Math.abs(balance) : 0;

    const handleConfirm = () => {
        const val = parseFloat(amount);
        if (!isNaN(val) && val > 0) {
            // Send signed amount: Negative if REFUND
            const finalAmount = mode === "REFUND" ? -val : val;
            onConfirm(finalAmount, note);
        }
    };

    const setFull = () => {
        if (mode === "PAY") {
            if (balance > 0) setAmount(balance.toString());
        } else {
            // Prefer refunding just the overpayment; fall back to full amount paid
            const refundMax = overpaidAmount > 0
                ? Math.min(currentPaid, overpaidAmount)
                : currentPaid;
            setAmount(refundMax.toString());
        }
    };

    const isRefund = mode === "REFUND";

    return (
        <div className="bg-white rounded-lg shadow-xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className={`px-6 py-4 border-b border-slate-100 flex justify-between items-center ${isRefund ? "bg-amber-50" : "bg-slate-50"}`}>
                <h3 className={`font-bold flex items-center gap-2 ${isRefund ? "text-amber-700" : "text-slate-900"}`}>
                    <Banknote className="h-5 w-5" />
                    {isRefund ? "Issue Refund / Correction" : "Add Payment"}
                </h3>
                <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
                    <X className="h-5 w-5" />
                </button>
            </div>

            <div className="p-6 space-y-4">
                {/* Mode Toggle */}
                <div className="bg-slate-100 p-1 rounded-lg flex relative">
                    <button
                        onClick={() => { setMode("PAY"); setAmount(""); }}
                        className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all z-10 ${mode === "PAY" ? "bg-white text-emerald-700 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
                    >
                        Add Payment
                    </button>
                    <button
                        onClick={() => { setMode("REFUND"); setAmount(""); }}
                        className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all z-10 ${mode === "REFUND" ? "bg-white text-amber-700 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
                    >
                        Refund / Correct
                    </button>
                </div>

                <div className="bg-slate-50 p-3 rounded border border-slate-200 space-y-3">
                    <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">
                            {balance < 0 ? "Overpaid" : "Remaining Balance"}
                        </span>
                        <span className={`font-bold text-lg ${balance < 0 ? "text-amber-700" : "text-rose-600"}`}>
                            ₱{Math.abs(balance).toLocaleString()}
                        </span>
                    </div>

                    {/* Method Selector in Modal */}
                    {!isRefund && ( // Only show method for payment? Or for refund too (refund via...)? Let's keep it for both
                        <div className="flex items-center justify-between border-t border-slate-100 pt-2">
                            <span className="text-xs font-semibold text-slate-500 uppercase">Method</span>
                            <select
                                value={paymentMethod}
                                onChange={e => onUpdatePaymentMethod(e.target.value)}
                                className="text-sm font-bold text-slate-900 border-none bg-transparent focus:ring-0 p-0 text-right cursor-pointer hover:text-emerald-600 w-auto"
                            >
                                <option value="CASH">Cash</option>
                                <option value="GCASH">GCash</option>
                                <option value="GOTYME">GoTyme</option>
                                <option value="BANK">Bank</option>
                            </select>
                        </div>
                    )}
                </div>

                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">
                        {isRefund ? "Amount to Refund/Deduct" : "Amount to Pay"}
                    </label>
                    <div className="relative">
                        <span className={`absolute left-3 top-2.5 font-bold ${isRefund ? "text-amber-500" : "text-slate-400"}`}>
                            {isRefund ? "-" : ""}₱
                        </span>
                        <input
                            type="number"
                            autoFocus
                            value={amount}
                            onChange={e => setAmount(e.target.value)}
                            className={`w-full pl-8 pr-20 py-2 text-lg font-bold border rounded focus:ring-opacity-50 ${isRefund
                                ? "text-amber-700 border-amber-200 focus:border-amber-500 focus:ring-amber-500 bg-amber-50/30"
                                : "text-slate-900 border-slate-300 focus:border-slate-900 focus:ring-slate-900" // Fixed: Removed recursive text-slate-900
                                }`}
                            placeholder="0.00"
                        />
                        <button
                            onClick={setFull}
                            className={`absolute right-1 top-1 bottom-1 px-3 text-xs font-bold rounded uppercase tracking-wide transition-colors ${isRefund
                                ? "text-amber-700 bg-amber-100 hover:bg-amber-200"
                                : "text-emerald-700 bg-emerald-50 hover:bg-emerald-100"
                                }`}
                        >
                            Max
                        </button>
                    </div>
                </div>

                {/* Optional Note */}
                <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Reason (Optional)</label>
                    <input
                        type="text"
                        value={note}
                        onChange={e => setNote(e.target.value)}
                        className="w-full text-sm border-slate-200 rounded-md focus:ring-slate-900 focus:border-slate-900"
                        placeholder={isRefund ? "e.g. Overpayment, Cancellation" : "e.g. Reference No. 123"}
                    />
                </div>
            </div>

            <div className="px-6 py-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
                <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg">Cancel</button>
                <button
                    onClick={handleConfirm}
                    disabled={!amount || parseFloat(amount) <= 0}
                    className={`px-4 py-2 text-sm font-bold text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed ${isRefund
                        ? "bg-amber-600 hover:bg-amber-700"
                        : "bg-slate-900 hover:bg-slate-800"
                        }`}
                >
                    {isRefund ? "Confirm Refund" : "Confirm Payment"}
                </button>
            </div>
        </div>
    );
};
